// The Zouave reacts: he leans towards the pointer, answers a poke, thinks while the tools run, looks worried when the
// water reaches the address, suggests what to ask next and lets visitors ask about any point of the map.
// Poses generated by scripts/avatar/poses_openai.mjs (poses.json) replace the CSS fallbacks when they exist.
import * as maplibregl from 'maplibre-gl';
import { map } from './map.ts';
import { followUps, moodFor, QUIPS, type Pose } from './followups.ts';
import { avatarVariant } from './avatar.ts';

interface Mascot { say: (text: string) => void; ask: (message: string) => void; askHere: (lat: number, lon: number) => void; busy: () => boolean }
let poseImages: Partial<Record<Pose, string>> = {};
let poseTimer: ReturnType<typeof setTimeout> | undefined;
const ring = () => document.getElementById('avatar-ring');
const touring = () => document.body.classList.contains('tour-active');

/** Shows a pose for a while (generated image when available, CSS motion otherwise), then back to neutral. */
export function setPose(pose: Pose | null, ms = 3500) {
  const element = ring(); if (!element) return;
  clearTimeout(poseTimer);
  element.classList.remove(...[...element.classList].filter(name => name.startsWith('pose-')), 'posed');
  const overlay = element.querySelector<HTMLImageElement>('.avatar-pose');
  if (!pose) return;
  void element.offsetWidth; // restart the CSS animation when the same pose comes back
  element.classList.add(`pose-${pose}`);
  if (overlay && poseImages[pose]) { overlay.src = poseImages[pose]!; element.classList.add('posed'); }
  if (ms > 0) poseTimer = setTimeout(() => setPose(null), ms);
}

/** After each answer: a mood, and three next questions as buttons under the answer. */
export function reactTo(question: string, answer: string) {
  const mood = moodFor(answer);
  if (mood || ring()?.classList.contains('pose-thinking')) setPose(mood, 4000);
  const box = document.getElementById('followups'); if (!box) return;
  box.replaceChildren(...followUps(question, answer).map(text => { const button = document.createElement('button'); button.type = 'button'; button.dataset.followup = text; button.textContent = text; return button; }));
  box.hidden = false;
}

function tilt(element: HTMLElement) {
  // Leans a few degrees towards the pointer; stays still for people who prefer reduced motion.
  if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  let frame = 0;
  window.addEventListener('pointermove', event => {
    if (frame) return;
    frame = requestAnimationFrame(() => {
      frame = 0;
      const box = element.getBoundingClientRect();
      const x = Math.max(-1, Math.min(1, (event.clientX - (box.left + box.width / 2)) / (innerWidth / 2)));
      const y = Math.max(-1, Math.min(1, (event.clientY - (box.top + box.height / 2)) / (innerHeight / 2)));
      element.style.setProperty('--lean-x', x.toFixed(3)); element.style.setProperty('--lean-y', y.toFixed(3));
    });
  }, { passive: true });
  document.addEventListener('pointerleave', () => { element.style.setProperty('--lean-x', '0'); element.style.setProperty('--lean-y', '0'); });
}

function nudges(mascot: Mascot) {
  // After a quiet minute the Zouave offers one question; at most three times, never during the story or an answer.
  const bubble = document.createElement('button');
  bubble.type = 'button'; bubble.className = 'zouave-nudge'; bubble.hidden = true;
  ring()!.append(bubble);
  const ideas = ['Psst… what about your home?', 'Want to see 1910?', 'Click the map: what about here?', 'Shall I read the Seine level now?'];
  const asks: Record<string, string> = { 'Psst… what about your home?': 'What about my home?', 'Want to see 1910?': 'Show me 1910', 'Shall I read the Seine level now?': 'Seine level now' };
  let shown = 0, timer: ReturnType<typeof setTimeout> | undefined;
  const hide = () => { bubble.hidden = true; };
  const arm = () => {
    clearTimeout(timer); hide();
    if (shown >= 3) return;
    timer = setTimeout(() => {
      if (touring() || mascot.busy() || document.querySelector('dialog[open]') || document.getElementById('hood')?.hidden === false) return arm();
      bubble.textContent = ideas[shown % ideas.length]; bubble.hidden = false; shown++;
      setPose('wave', 2500);
      timer = setTimeout(arm, 9000);
    }, 60_000);
  };
  bubble.addEventListener('click', event => { event.stopPropagation(); const ask = asks[bubble.textContent ?? '']; hide(); if (ask) mascot.ask(ask); else mascot.say('Click anywhere on the map, then ask me: what about here?'); });
  for (const type of ['pointerdown', 'keydown', 'wheel']) window.addEventListener(type, arm, { passive: true });
  arm();
}

function askAnywhere(mascot: Mascot) {
  // A click on the map (not a drag, not a marker) offers "What about here?"; the answer uses the same tools as an address.
  const popup = new maplibregl.Popup({ closeButton: false, offset: 10, className: 'here-popup' });
  map.on('click', event => {
    if (touring()) return;
    const target = event.originalEvent.target as HTMLElement | null;
    if (target?.closest('.maplibregl-marker, .maplibregl-popup')) return;
    const { lat, lng } = event.lngLat;
    const button = document.createElement('button');
    button.type = 'button'; button.className = 'here-button';
    button.innerHTML = '<img src="/zouave/' + avatarVariant() + '/avatar.webp" alt=""><span>What about <b>here</b>?</span>';
    button.addEventListener('click', () => { popup.remove(); setPose('point', 2500); mascot.askHere(lat, lng); });
    popup.setLngLat(event.lngLat).setDOMContent(button).addTo(map);
  });
}

export async function initializeMascot(mascot: Mascot) {
  const element = ring(); if (!element) return;
  const overlay = new Image(); overlay.className = 'avatar-pose'; overlay.alt = ''; overlay.setAttribute('aria-hidden', 'true');
  element.append(overlay);
  tilt(element);
  // Poke the statue: a quip, a wave, and the usual suggestions.
  let quip = 0;
  element.setAttribute('role', 'button'); element.tabIndex = 0; element.title = 'Poke the Zouave';
  const poke = () => {
    if (mascot.busy()) { setPose('thinking', 1500); return; }
    setPose((['wave', 'laugh', 'surprised', 'salute', 'proud', 'present'] as const)[quip % 6], 2600);
    const line = QUIPS[quip++ % QUIPS.length];
    mascot.say(line);
    reactTo('', line);
  };
  element.addEventListener('click', event => { if ((event.target as HTMLElement).closest('.zouave-nudge')) return; poke(); });
  element.addEventListener('keydown', event => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); poke(); } });
  document.getElementById('followups')?.addEventListener('click', event => {
    const button = (event.target as HTMLElement).closest<HTMLButtonElement>('[data-followup]');
    if (button) mascot.ask(button.dataset.followup!);
  });
  window.addEventListener('zouave:trace', event => { const name = (event as CustomEvent<{ name: string }>).detail.name; if (name === 'aller_a' || name === 'aller_au_point') setPose('point', 2400); });
  nudges(mascot);
  askAnywhere(mascot);
  const manifest = await fetch(`/zouave/${avatarVariant()}/poses.json`).then(response => response.ok ? response.json() : null).catch(() => null);
  if (manifest?.poses) poseImages = Object.fromEntries(Object.entries(manifest.poses as Record<string, string>).map(([pose, file]) => [pose, `/zouave/${avatarVariant()}/${file}`]));
  // Preload them, so a pose never appears blank the first time.
  for (const src of Object.values(poseImages)) new Image().src = src!;
  // Listening to the microphone: a hand behind the ear.
  new MutationObserver(() => {
    const listening = element.classList.contains('listening');
    const posing = [...element.classList].some(name => name.startsWith('pose-'));
    if (listening && !posing) setPose('listen', 0);
    else if (!listening && element.classList.contains('pose-listen')) setPose(null);
  }).observe(element, { attributes: true, attributeFilter: ['class'] });
}
